(* [comment removed for export] *)
Definition PAYC (i : nat) (p : Z) : Prop := if EVDNA.WDD i then 1 <= p <= 28 else if EVDNA.AD i then p = 4 else p = 0.
(* [comment removed for export] *)
Definition gbump (g : eghost) : eghost := EG (bump (g_es g)) (g_len g) (g_rep g) (g_sb g) (g_scap g).
Definition GI (i : nat) (g : eghost) : eghost := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S00$i;R+^6$g;R+^7-GRN$~R+G+^7!1'^8#22!1'^9#1#1").

Theorem visit_double_nested_ok : forall (LBo : list (Z * Z)) (FF LK : list fframe) (cr : credit) (A : list (Z * Z)) (sp r V S2 kx bx : Z) (g : eghost) (c0 : ectx) (r0 : estate),
  g_es g = c0 :: r0 ->
  PMSA.cps_asan L ar HI EVDNA.PC r sp (PMESA.VIS_SCRA 12800) (LBo ++ g_lbv g) FF LK cr A PMESA.VIS_D
    (fun R M => PMSA.a0 R V /\ True /\ sp mod 32 = 0 /\ PMSA.stksh ar M sp (PMESA.VIS_SCRA 12800) /\ PMESA.enc_invA L IC EC M V S2 g /\ ev_guard (g_es g) EvDbl /\
                PMESA.eroomA CL g EvDbl /\ PMLA.img_ro IC M /\ PMESA.lits_ok L IC M /\ PMESA.ecreditA L CL cr g kx bx /\
                PMSA.fobj M FF V ENC_SIZE /\ PMSA.fobj M FF S2 24 /\ PMLA.apart V ENC_SIZE S2 24)
    (fun R M R' M' LB' cr' LBk W => exists (g' : eghost) (pay : Z),
        PMSA.a0 R' 1 /\ PMESA.enc_invA L IC EC M' V S2 g' /\ g_es g' = estep (g_es g) EvDbl /\ pay_ok EvDbl pay /\ g_len g' = g_len g + ev_ind (g_es g) EvDbl + pay /\
        PMESA.lits_ok L IC M' /\ LB' = LBo ++ g_lbv g' /\ LBk = LBo /\ W = PMESA.W_encA IC V S2 ++ [(hl_tp L - 164, 4)] /\ PMESA.ecreditA L CL cr' g' kx bx).
